<template>
  <section class="exploration-data-table" aria-label="分析数据预览"><div class="exploration-table-scroll"><table><thead><tr><th v-for="(column,index) in table.columns" :key="index" :aria-sort="sortColumn===index?(sortDirection==='asc'?'ascending':'descending'):'none'"><button type="button" @click="sort(index)">{{ column }}<span aria-hidden="true">{{ sortColumn===index?(sortDirection==='asc'?' ↑':' ↓'):' ↕' }}</span></button></th></tr></thead><tbody><tr v-for="(row,index) in pageRows" :key="index"><td v-for="(cell,col) in row" :key="col">{{ cell ?? '—' }}</td></tr></tbody></table></div><footer><span>{{ table.rows.length }} 条<span v-if="table.truncated">（预览上限）</span></span><div><button type="button" aria-label="上一页数据" :disabled="page<=1" @click="page--">‹</button><span>{{ page }} / {{ pageCount }}</span><button type="button" aria-label="下一页数据" :disabled="page>=pageCount" @click="page++">›</button><select v-model.number="pageSize" aria-label="每页数据条数" @change="page=1"><option :value="5">5 条 / 页</option><option :value="10">10 条 / 页</option><option :value="20">20 条 / 页</option></select></div></footer></section>
</template>
<script src="../js/components/ExplorationDataTable.js"></script>
<style scoped src="../styles/components/exploration-data-table.css"></style>
